import{_ as a,H as t,f as n,i as r}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"结束语｜时代飞速更迭，你我携手同行","description":"","frontmatter":{},"headers":[{"level":2,"title":"不变之一：世界的复杂性","slug":"不变之一-世界的复杂性","link":"#不变之一-世界的复杂性","children":[]},{"level":2,"title":"不变之一：关系的可贵性","slug":"不变之一-关系的可贵性","link":"#不变之一-关系的可贵性","children":[]},{"level":2,"title":"时代加速变化，我们如何前行？","slug":"时代加速变化-我们如何前行","link":"#时代加速变化-我们如何前行","children":[{"level":3,"title":"思考深度","slug":"思考深度","link":"#思考深度","children":[]},{"level":3,"title":"学习速度","slug":"学习速度","link":"#学习速度","children":[]},{"level":3,"title":"抱团取暖","slug":"抱团取暖","link":"#抱团取暖","children":[]}]}],"relativePath":"ClaudeCode工程化实战/结束语｜时代飞速更迭，你我携手同行.md","filePath":"ClaudeCode工程化实战/结束语｜时代飞速更迭，你我携手同行.md","lastUpdated":1779815462000}'),s={name:"ClaudeCode工程化实战/结束语｜时代飞速更迭，你我携手同行.md"};function i(l,e,o,p,h,d){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="结束语-时代飞速更迭-你我携手同行" tabindex="-1">结束语｜时代飞速更迭，你我携手同行 <a class="header-anchor" href="#结束语-时代飞速更迭-你我携手同行" aria-label="Permalink to &quot;结束语｜时代飞速更迭，你我携手同行&quot;">​</a></h1><p>你好，我是黄佳。</p><p>特别开心来到了结束语这个篇章。来到这个篇章，意味着你已经学完了这个课程，而我也已经写完了整个专栏。</p><p>Claude Code的任何重要演进，我会给大家及时加餐或者通过直播来分享的，因此我在结束语部分就不说技术和课程的事儿，我只说一说从开课（1月28日）到此刻（4月15日）我的心路变迁。</p><p>“一日不见，如三秋兮”，这句话出自《诗经·王风·采葛》，以 <strong>夸张</strong> 手法表达对亲友的深切思念。在 AI 时代，反而变得不那么夸张。就这短短的几个月专栏创作期间，我们经历了OpenClaw从大流行到热度消退，Harness Engineering概念从天而降，Claude Code源码深夜泄露，以及Hermes取代OpenClaw引领新的潮流…</p><p>如果你一天没刷手机，第二天听到大家都在谈论全新的名词，而你却全然无知，你是否会觉得自己非常失落，甚至觉得是身处另一个世界。这样一幕你是否有点眼熟：“ <strong>啊？！你居然没听说过Hermes？？？</strong>”</p><p>这其实是一个非常荒谬的事情。</p><p>因此在这个被加速的年代，我们反而要把自己的心态稳定下来。大家一起思考一下，在这个时代 <strong>什么东西其实并没有变</strong>。 <strong>什么东西是真正值得的</strong>。</p><h2 id="不变之一-世界的复杂性" tabindex="-1">不变之一：世界的复杂性 <a class="header-anchor" href="#不变之一-世界的复杂性" aria-label="Permalink to &quot;不变之一：世界的复杂性&quot;">​</a></h2><p>这个世界其实从来都是复杂的，而这也是我们工程师存在的根本原因。</p><p>图片参考了我在 Datawhale 做的分享整理而来，如果你对我前阵子在Datawhale带来的 Agent Harness 分享感兴趣，可以查看 <a href="https://mp.weixin.qq.com/s/nPxWGkITw4f92aI_P3Rn-Q" target="_blank" rel="noreferrer">这个链接</a>。</p><p>我们工程师一直都是在跟系统的复杂度做斗争。技术架构演进二十几年不变的是什么？ <strong>不变的就是如何驾驭复杂性。</strong> 我们驾驭了对象，我们驾驭了系统架构，我们驾驭了分布式，我们驾驭了微服务… 我们所做的所有努力，都是希望能够降低复杂系统的复杂度。现在，轮到我们工程师去驾驭这个充满AI的崭新世界。</p><p>这个世界可以快速变化，但是我们仍然要用工程师的耐心、智慧和勇气，去勇敢的应战，并且通过抽象能力加上结构化，把很乱的东西里边的本质抓出来，让复杂的新世界变得更容易驾驭。</p><p>正如我的一个群友留言所说：“我们是从分布式、微服务，云计算和大数据时代存活过来的工程师，我不会觉得Agent时代的技术有什么了不起的。我们可以的。”—— 我非常同意这个看法。我们可以的。</p><h2 id="不变之一-关系的可贵性" tabindex="-1">不变之一：关系的可贵性 <a class="header-anchor" href="#不变之一-关系的可贵性" aria-label="Permalink to &quot;不变之一：关系的可贵性&quot;">​</a></h2><p>人和人之间的连接很珍贵。在AI到处都是的年代尤其如此。越是AI，越呼唤人和人之间真正的接触和友谊，而技术可以是桥梁。</p><p>在课程上线之初，我就收获了大家大量的发自内心的支持，这种能量我感受到了，也形成了我的创作来源。</p><p>大厂资深工程师“6点起床学习的和尚”在专栏中持续贡献高价值评论，得到了大家的点赞和认可。有学员留言“和尚实战经验丰富，极客时间可否邀请佳哥和和尚共创一集内容？”</p><p>在专栏临近结束，我最新的公开分享中，真的邀请到了和尚，和他详细取经，共创出SDD落地真实场景，奉献给大家。大家的愿望成真了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/967306/7fa01dafe682c948baa7bfe40ee19e8e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/967306/7fa01dafe682c948baa7bfe40ee19e8e.png" alt="图片"></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/967306/7a5245e75dc9458191b8939f72c6a6e4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/967306/7a5245e75dc9458191b8939f72c6a6e4.png" alt="图片"></a></p><p>技术之外，佳哥感受到的都是大家满满的学习热情，以及和尚全心全意在百忙的工作中（10点才下班，6点又要起床）的浓浓友情。</p><p>有这些东西支撑着，我们就没那么害怕AI了。</p><h2 id="时代加速变化-我们如何前行" tabindex="-1">时代加速变化，我们如何前行？ <a class="header-anchor" href="#时代加速变化-我们如何前行" aria-label="Permalink to &quot;时代加速变化，我们如何前行？&quot;">​</a></h2><p>好，再来说说我们应该如何前行。因为时代的加速变化是真实存在的，任何人都要做好应对，何况是走在技术前沿的我们。简单来说，我觉得这三点更重要了。</p><h3 id="思考深度" tabindex="-1">思考深度 <a class="header-anchor" href="#思考深度" aria-label="Permalink to &quot;思考深度&quot;">​</a></h3><p>一定要把问题想深，想透。要把思考当乐趣。你的思考深度和刨根问底的精神将成为你和他人的分水岭。AI 时代你多了一个思考的对手和战友，你要利用好这个战友。它是个威胁，同时也是最好的礼物。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/967306/7c0fd664dabda8ayy1feb35650328e9b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/967306/7c0fd664dabda8ayy1feb35650328e9b.png" alt="图片"></a></p><h3 id="学习速度" tabindex="-1">学习速度 <a class="header-anchor" href="#学习速度" aria-label="Permalink to &quot;学习速度&quot;">​</a></h3><p>学而时习之，不亦说乎。爱学习的人在 AI 时代有福了。因为你拥有了一个最好的助手和学习搭子。学习的成本也变得很低。如果你不喜欢学习，我很难想象你将以什么样的感受与你后续的几十年人生同处。</p><p>我真心希望更多人能够喜欢上大脑神经元更新的感觉，就像大模型的训练过程一样，越训练越强，越训练越快。神经元越改变，你从这个世界上获取的信息越真实（很多我们原本以为是真实的东西并不是真的）。</p><p>学习的过程其实是改变自己旧观念的过程，对于所有的旧观念，我们要舍得抛弃，舍得改变。这需要勇气，因为每个人似乎都很执着于“旧”的自己。我不知道为什么。我更喜欢改变后的、更新的自己。</p><h3 id="抱团取暖" tabindex="-1">抱团取暖 <a class="header-anchor" href="#抱团取暖" aria-label="Permalink to &quot;抱团取暖&quot;">​</a></h3><p>我们真的很需要携手同行。佳哥不是什么大师，我只是一个愿意带着大家一起学习的人。我所有的群（最早的已经7、8年了），从来没冷清过。很多群都很快凉了，佳哥的群越来越热闹。大家讨论最新技术、彼此介绍工作机会，甚至交友，征婚（真的）。</p><p>因为群友说，只要是欣赏佳哥的，肯定爱学习，肯定正能量。—— 我深以为然。（广告：佳哥的群逐渐都满了。如果你有需要，除了课程群，你还可以通过极客时间最近开设的 <a href="https://u.geekbang.org/subject/intro/1011199" target="_blank" rel="noreferrer">行动营</a>，或者搜索“咖哥AI”付费支持佳哥，加入佳哥的星球。）</p><p>想说的话非常多，好在分享的机会也非常多，今天先聊到这里。感恩有你一路相伴，我们下个专栏再见！</p><p>这门课程的正文内容即将落下帷幕，感谢大伙儿一路支持相伴，一起讨论交流（这个交流我们还可以继续），也希望你可以花几分钟填一下 <a href="https://geekbang.feishu.cn/share/base/form/shrcnx5cfYuDK9q8ss0tgulv5hh" target="_blank" rel="noreferrer">课程问卷</a>，我会认真参考大伙儿的反馈建议。</p><p><a href="https://geekbang.feishu.cn/share/base/form/shrcnx5cfYuDK9q8ss0tgulv5hh" target="_blank" rel="noreferrer"><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/967306/43fd5c86f994a3ca530ea06bdceae241.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/967306/43fd5c86f994a3ca530ea06bdceae241.jpg" alt=""></a></a></p>',38)])])}const u=a(s,[["render",i]]);export{g as __pageData,u as default};
